PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,senha TEXT NOT NULL,tipo TEXT NOT NULL DEFAULT 'cliente' CHECK(tipo IN ('cliente','adm')),data_cadastro TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categorias (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE,descricao TEXT,ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN(0,1)));
CREATE TABLE IF NOT EXISTS produtos (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,descricao TEXT NOT NULL,preco INTEGER NOT NULL CHECK(preco>=0),id_categoria INTEGER NOT NULL REFERENCES categorias(id),estoque INTEGER NOT NULL DEFAULT 0 CHECK(estoque>=0),imagem TEXT,destaque INTEGER NOT NULL DEFAULT 0 CHECK(destaque IN(0,1)),ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN(0,1)));
CREATE TABLE IF NOT EXISTS pedidos (id INTEGER PRIMARY KEY AUTOINCREMENT,id_usuario INTEGER NOT NULL REFERENCES usuarios(id),valor_total INTEGER NOT NULL CHECK(valor_total>=0),status TEXT NOT NULL DEFAULT 'pendente',data_pedido TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS itens_pedido (id INTEGER PRIMARY KEY AUTOINCREMENT,id_pedido INTEGER NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE,id_produto INTEGER NOT NULL REFERENCES produtos(id),quantidade INTEGER NOT NULL CHECK(quantidade>0),preco_unitario INTEGER NOT NULL CHECK(preco_unitario>=0));
CREATE TABLE IF NOT EXISTS tickets (id INTEGER PRIMARY KEY AUTOINCREMENT,id_usuario INTEGER REFERENCES usuarios(id),nome TEXT NOT NULL,email TEXT NOT NULL,assunto TEXT NOT NULL,mensagem TEXT NOT NULL,categoria TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'aberto',criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_produtos_categoria ON produtos(id_categoria);
CREATE INDEX IF NOT EXISTS idx_pedidos_usuario ON pedidos(id_usuario);